1) The following code demonstrates a function that converts the string input into a list of strings by removing all punctuation characters, and then reorders the resulting list using a custom sorting algorithm based on the length of each word:

function reorder(input) {
    var output = input.split(' ').filter(function(word){return !word.includes("\\\\")});
    output.sort(function(a,b){return b.length-a.length});
    return output.join(' ');
}

